export function t(key: keyof typeof STR | string, lang: Lang): string {
  const row = STR[key];
  if (!row) return String(key);
  return lang === "ur" ? row.ur : lang === "en" ? row.en : row.roman;
}

export function fill(text: string, vars: Record<string, string>): string {
  return text.replace(/\{(\w+)\}/g, (_, k: string) => vars[k] ?? `{${k}}`);
}

export function getStoredLang(): Lang {
  if (typeof window === "undefined") return "roman";
  const v = window.localStorage.getItem("munshi-lang");
  return v === "ur" || v === "en" ? v : "roman";
}

export function saleStatusLabel(s: string, lang: Lang): string {
  const map: Record<string, string> = { Paid: "ss_paid", "Partially paid": "ss_partial", Unpaid: "ss_unpaid", Reversed: "ss_reversed" };
  return t(map[s] ?? s, lang);
}

export function custBadgeLabel(b: string, lang: Lang): string {
  const map: Record<string, string> = { Safe: "ss_safe", "Near limit": "ss_near", Blocked: "ss_blocked" };
  return t(map[b] ?? b, lang);
}

